input.command:
for eid in 16838 16836 16834 16833 16831 16830 16829 16828 16827 16826 16825; do
  result=$(curl -s -H "X-N8N-API-KEY: eyJ.[REDACTED-JWT]" \
    "https://xprime17.app.n8n.cloud/api/v1/executions/$eid?includeData=true" | python3 -c "
import json, sys
d = json.load(sys.stdin)
rd = d.get('data', {}).get('resultData', {}) or d.get('resultData', {})
run_data = rd.get('runData', {})
caller = None
for node, runs in run_data.items():
    for r in runs:
        out = r.get('data', {}).get('main', [])
        for bucket in out:
            if not bucket: continue
            for item in bucket:
                s = json.dumps(item.get('json',{}))
                for n in ['Jennifer Park','David Chen','Helena Ivanov','Priya','Rachel','Brianna','Amara','Thomas','Marcus']:
                    if n in s and not caller:
                        caller = n
event = None
for node, runs in run_data.items():
    for r in runs:
        out = r.get('data', {}).get('main', [])
        for bucket in out:
            if not bucket: continue
            for item in bucket:
                j = item.get('json',{})
                if 'event' in j:
                    event = j['event']
                    break
print(f'caller={caller} event={event} nodes={list(run_data.keys())[:8]}')
")
  echo "exec $eid: $result"
done

