import json
import urllib.request
import urllib.error

API_KEY = "eyJ.[REDACTED-JWT]"
BASE = "https://xprime17.app.n8n.cloud/api/v1"

# Code node: extract plaintext from Google Docs structure + build Retell pre-call response
EXTRACT_CODE = r"""
// Google Docs `get` returns body.content as an array of structural elements.
// Extract plaintext by walking paragraphs → elements → textRun.content
const doc = $input.first().json;
const body = doc.body || {};
const content = body.content || [];
const parts = [];
for (const el of content) {
  const para = el.paragraph;
  if (!para) continue;
  for (const pe of (para.elements || [])) {
    const tr = pe.textRun;
    if (tr && tr.content) parts.push(tr.content);
  }
}
const kb = parts.join('').trim();
// Retell pre-call webhook spec: respond with { call_inbound: { dynamic_variables: {...} } }
return [{
  json: {
    call_inbound: {
      dynamic_variables: {
        knowledge_base: kb
      }
    }
  }
}];
"""

workflow = {
    "name": "Inbound Pre-Call KB Injection - EG",
    "nodes": [
        {
            "parameters": {
                "httpMethod": "POST",
                "path": "inbound-kb-injection-eg",
                "responseMode": "responseNode",
                "options": {}
            },
            "id": "node-webhook",
            "name": "Webhook",
            "type": "n8n-nodes-base.webhook",
            "typeVersion": 2,
            "position": [240, 300],
            "webhookId": "inbound-kb-injection-eg"
        },
        {
            "parameters": {
                "operation": "get",
                "documentURL": "https://docs.google.com/document/d/1QTvkO1d72KYIi2ALtPEIrOASsbxggxeyCRiS1rWK3Ek/edit"
            },
            "id": "node-getkb",
            "name": "Get KB",
            "type": "n8n-nodes-base.googleDocs",
            "typeVersion": 2,
            "position": [460, 300],
            "credentials": {
                "googleDocsOAuth2Api": {
                    "id": "58qerrOCaSjZ51WF",
                    "name": "Google Docs account"
                }
            }
        },
        {
            "parameters": {
                "jsCode": EXTRACT_CODE
            },
            "id": "node-extract",
            "name": "Extract Text + Build Response",
            "type": "n8n-nodes-base.code",
            "typeVersion": 2,
            "position": [680, 300]
        },
        {
            "parameters": {
                "respondWith": "firstIncomingItem",
                "options": {}
            },
            "id": "node-respond",
            "name": "Respond to Webhook",
            "type": "n8n-nodes-base.respondToWebhook",
            "typeVersion": 1.1,
            "position": [900, 300]
        }
    ],
    "connections": {
        "Webhook": {
            "main": [[{"node": "Get KB", "type": "main", "index": 0}]]
        },
        "Get KB": {
            "main": [[{"node": "Extract Text + Build Response", "type": "main", "index": 0}]]
        },
        "Extract Text + Build Response": {
            "main": [[{"node": "Respond to Webhook", "type": "main", "index": 0}]]
        }
    },
    "settings": {
        "executionOrder": "v1"
    }
}

# Create workflow
req = urllib.request.Request(
    f"{BASE}/workflows",
    data=json.dumps(workflow).encode(),
    headers={"X-N8N-API-KEY": API_KEY, "Content-Type": "application/json"},
    method="POST"
)
try:
    with urllib.request.urlopen(req, timeout=30) as resp:
        result = json.load(resp)
        print(f"CREATED: id={result.get('id')} name={result.get('name')}")
        print(f"active: {result.get('active')}")
except urllib.error.HTTPError as e:
    print(f"ERROR {e.code}: {e.read().decode()[:500]}")

