  // Leaside — add phone here once Retell inbound agent + forwarding is live
  //   Doc URL: https://docs.google.com/document/d/1hDmMP6565YUXbXu9srTpADGBhZy8xt4woODiqfsoSDI/edit
};

const payload = $input.first().json;
const body = payload.body || payload;
const inbound = body.call_inbound || {};
const toNumber = inbound.to_number || body.to_number || '';

const centre = PHONE_TO_CENTRE[toNumber];
if (!centre) {
  // Fail-open: return a marker so Build Response returns empty KB. Call proceeds
  // without context rather than failing. Search n8n executions for 'kb_missing=true'
  // to find misconfigured phones.
  return [{ json: {
    to_number: toNumber,
    centre_id: 'unknown',
    documentURL: '',
    kb_missing: true,
    warning: `No KB mapping for to_number='${toNumber}'. Add entry to PHONE_TO_CENTRE.`
  } }];
}
return [{ json: {
  to_number: toNumber,
  centre_id: centre.centre_id,
  documentURL: centre.documentURL,
  kb_missing: false
} }];
"""

# IF node: route known→Get KB, unknown→skip to Build Response with empty kb
# For simplicity, use Code-level fallback: always call Get KB with guard, Build handles both
BUILD_RESPONSE_CODE = r"""
// Two input shapes:
//   From Get KB (known centre): { documentId, content }
//   From Resolve Centre (unknown, skipped Get KB): { kb_missing: true, warning, ... }
const item = $input.first().json;

let kb = '';
if (item.content !== undefined) {
  kb = (item.content || '').trim();
} else if (item.kb_missing) {
  // Explicit empty KB; surface warning in n8n execution output for debugging
  kb = '';
}

return [{ json: {
  call_inbound: { dynamic_variables: { knowledge_base: kb } },
  _debug: { kb_len: kb.length, kb_missing: item.kb_missing || false, warning: item.warning || null }
} }];
"""

# Respond returns only `call_inbound`, stripping _debug
RESPOND_CODE = r"""
// Strip debug fields from final webhook response.
const item = $input.first().json;
return [{ json: { call_inbound: item.call_inbound } }];
"""

# Fetch current
with urllib.request.urlopen(urllib.request.Request(
    f"{BASE}/workflows/{WF_ID}", headers={"X-N8N-API-KEY": API_KEY}
), timeout=30) as resp:
    wf = json.load(resp)

# Rebuild node graph with IF-based branching:
# Webhook → Resolve Centre → IF (kb_missing?) → [false: Get KB → Merge]
#                                                 [true: --------→ Merge]
#                              → Build Response → Respond to Webhook
new_nodes = [
    {
        "parameters": {"httpMethod": "POST", "path": "inbound-kb-injection-eg",
                       "responseMode": "responseNode", "options": {}},
        "id": "node-webhook", "name": "Webhook",
        "type": "n8n-nodes-base.webhook", "typeVersion": 2,
        "position": [240, 300], "webhookId": "inbound-kb-injection-eg"
    },
    {
        "parameters": {"jsCode": RESOLVE_CODE},
        "id": "node-resolve", "name": "Resolve Centre",
        "type": "n8n-nodes-base.code", "typeVersion": 2,
        "position": [440, 300]
    },
    {
        "parameters": {
            "conditions": {
                "options": {"caseSensitive": True, "typeValidation": "strict", "version": 2},
                "conditions": [{
                    "id": "c1",
                    "leftValue": "={{ $json.kb_missing }}",
                    "rightValue": True,
                    "operator": {"type": "boolean", "operation": "true"}
                }],
                "combinator": "and"
            },
            "options": {}
        },
        "id": "node-if", "name": "KB Missing?",
        "type": "n8n-nodes-base.if", "typeVersion": 2,
        "position": [640, 300]
    },
    {
        "parameters": {"operation": "get", "documentURL": "={{ $json.documentURL }}"},
        "id": "node-getkb", "name": "Get KB",
        "type": "n8n-nodes-base.googleDocs", "typeVersion": 2,
        "position": [840, 380],
        "credentials": {"googleDocsOAuth2Api": {"id": "58qerrOCaSjZ51WF", "name": "Google Docs account"}}
    },
    {
        "parameters": {"jsCode": BUILD_RESPONSE_CODE},
        "id": "node-build", "name": "Build Response",
        "type": "n8n-nodes-base.code", "typeVersion": 2,
        "position": [1040, 300]
    },
    {
        "parameters": {"respondWith": "firstIncomingItem", "options": {}},
        "id": "node-respond", "name": "Respond to Webhook",
        "type": "n8n-nodes-base.respondToWebhook", "typeVersion": 1.1,
        "position": [1240, 300]
    }
]

# Connections: IF true (kb_missing) → Build Response directly; false → Get KB → Build Response
new_connections = {
    "Webhook": {"main": [[{"node": "Resolve Centre", "type": "main", "index": 0}]]},
    "Resolve Centre": {"main": [[{"node": "KB Missing?", "type": "main", "index": 0}]]},
    "KB Missing?": {
        "main": [
            [{"node": "Build Response", "type": "main", "index": 0}],  # true: skip Get KB
            [{"node": "Get KB", "type": "main", "index": 0}]           # false: fetch
        ]
    },
    "Get KB": {"main": [[{"node": "Build Response", "type": "main", "index": 0}]]},
    "Build Response": {"main": [[{"node": "Respond to Webhook", "type": "main", "index": 0}]]}
}

wf["nodes"] = new_nodes
wf["connections"] = new_connections

# Strip read-only fields
for k in ["id","createdAt","updatedAt","description","isArchived","meta","pinData",
         "versionId","activeVersionId","versionCounter","triggerCount","shared",
         "activeVersion","active","tags"]:
    wf.pop(k, None)
wf.get("settings", {}).pop("availableInMCP", None)
wf.get("settings", {}).pop("timeSavedMode", None)

def api(path, method, body=None):
    req = urllib.request.Request(
        f"{BASE}{path}", method=method,
        headers={"X-N8N-API-KEY": API_KEY, "Content-Type": "application/json"},
        data=json.dumps(body).encode() if body else None
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        return resp.read()

try:
    api(f"/workflows/{WF_ID}/deactivate", "POST")
    api(f"/workflows/{WF_ID}", "PUT", wf)
    api(f"/workflows/{WF_ID}/activate", "POST")
    print("OK — multicentre workflow with fail-open routing")
except urllib.error.HTTPError as e:
    print(f"FAIL {e.code}: {e.read().decode()[:700]}")
    raise SystemExit(1)

